queries.02_club_rankings.sql:
-- CTE + window function: compare buyers within each destination league.
WITH ranked AS (
  SELECT *, DENSE_RANK() OVER (PARTITION BY league ORDER BY reported_permanent_fees_gbp DESC) AS league_spend_rank
  FROM v_club_buying
  WHERE league IN ('Premier League','La Liga','Serie A','Bundesliga','Ligue 1')
) SELECT * FROM ranked WHERE league_spend_rank<=5 ORDER BY league,league_spend_rank;

queries.03_largest_reported_transfers.sql:
SELECT record_id,player_name,from_club,to_club,to_league,quoted_fee_gbp,quote_basis,source_url
FROM summer_transfers WHERE is_permanent_fee=1
ORDER BY quoted_fee_gbp DESC LIMIT 20;

queries.06_fee_component_join.sql:
-- Aggregate components before joining to avoid multiplying transfer records.
WITH component_counts AS (
  SELECT record_id,COUNT(*) AS component_count FROM fee_components GROUP BY record_id
) SELECT t.record_id,t.player_name,t.quoted_fee_gbp,t.quote_basis,c.component_count
FROM summer_transfers t JOIN component_counts c ON t.record_id=c.record_id
ORDER BY c.component_count DESC,t.record_id;
